import numpy as np
def equation(eps, T, params):
    a,b,c,d = params[:4]
    return -a*np.exp(b*T)*eps**(c + d*T)

import numpy as np
def equation(eps, T, params):
    a,b,c,d,g,h,k,m = params[:8]
    num = a + b*T + (c + d*T)*eps + g*eps**2
    den = 1 + h*eps + m*eps*T
    return -eps*num/den*np.exp(-k*eps)
